<?php
$name=''; $age=''; $message=''; $allowed=false; $valid=false;
if($_SERVER['REQUEST_METHOD']==='POST'){
  $name=trim($_POST['name']??''); $ageInput=$_POST['age']??'';
  if($name==='' || mb_strlen($name)>80 || filter_var($ageInput,FILTER_VALIDATE_INT)===false || (int)$ageInput<0 || (int)$ageInput>120){$message='Please enter a valid name and an age between 0 and 120.';}
  else{$valid=true;$age=(int)$ageInput;$allowed=$age>=18;$safe=htmlspecialchars($name,ENT_QUOTES,'UTF-8');$message=$allowed?"Welcome to this site, {$safe}!":"Hello {$safe}, you are not authorized to visit the site.";}
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PHP Age Verification</title><link rel="stylesheet" href="../assets/style.css">    <link rel="stylesheet" href="style.css">
</head><body><header class="site-header"><div class="container"><a class="brand" href="../index.html">WP<span> / LAB 12</span></a><a class="back-link" href="../index.html">← All experiments</a></div></header><main class="container"><section class="hero"><span class="eyebrow">Experiment 12 · PHP conditional statements</span><h1>Age <span>Verification</span></h1><p class="lead">Enter your name and age. The PHP program checks whether the visitor is at least 18 years old.</p></section><section class="card" style="max-width:650px"><form method="post"><label for="name">Visitor name</label><input id="name" name="name" maxlength="80" required value="<?= htmlspecialchars($name,ENT_QUOTES,'UTF-8') ?>" placeholder="Enter your name"><label for="age">Age (in years)</label><input id="age" name="age" type="number" min="0" max="120" required value="<?= htmlspecialchars((string)$age,ENT_QUOTES,'UTF-8') ?>" placeholder="Enter your age"><div class="actions"><button type="submit">Check access →</button><a class="button secondary" href="index.php">Reset</a></div></form><?php if($message!==''): ?><div class="notice <?= $valid?($allowed?'success':'warning'):'warning' ?>" role="status"><strong><?= $valid?($allowed?'Access granted':'Access denied'):'Input error' ?></strong><p><?= htmlspecialchars($message,ENT_QUOTES,'UTF-8') ?></p></div><?php endif; ?></section></main></body></html>